package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/**
 * A statement taken of a person: their due-total and how many of their claims counted, as of the date it was taken as
 * of (the sheet's today, unless an earlier date was given).
 */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The date the statement was taken as of. */
    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    /** The sheet's today when the statement was taken; null for one taken before that was kept. */
    @Column(name = "made_on")
    private LocalDate madeOn;

    /** Two decimals, or n/a when the person's due-total had none. */
    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    /** Where the statement stands among its person's statements (in the order of seq, then id). */
    @Column(name = "seq", nullable = false)
    private long seq;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, LocalDate madeOn, String dueTotal, int claims,
            long seq) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.madeOn = madeOn;
        this.dueTotal = dueTotal;
        this.claims = claims;
        this.seq = seq;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public LocalDate getMadeOn() {
        return madeOn;
    }

    /** Whether the statement was taken while the sheet's today was on or before the date. */
    public boolean madeBy(LocalDate date) {
        return madeOn == null || !madeOn.isAfter(date);
    }

    public String getDueTotal() {
        return dueTotal;
    }

    public int getClaims() {
        return claims;
    }

    public long getSeq() {
        return seq;
    }

    /** The statement follows a person to the other person (on their sheet), standing at the place given. */
    public void moveTo(String sheetId, Long personId, long seq) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.seq = seq;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import net.officefloor.hq.app.person.Person;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** A sheet's statements, each person's in their order (the last is the person's last statement). */
    List<Statement> findBySheetIdOrderBySeqAscIdAsc(String sheetId);

    List<Statement> findBySheetIdAndPersonIdOrderBySeqAscIdAsc(String sheetId, Long personId);

    /**
     * The statements of one person follow them to another (on the other's sheet): counted with the other's own, placed
     * before them so the other's last statement stays theirs (or, having none, becomes the last of those that follow).
     */
    default void follow(Person from, Person into) {
        List<Statement> theirs = findBySheetIdAndPersonIdOrderBySeqAscIdAsc(from.getSheetId(), from.getId());
        List<Statement> own = findBySheetIdAndPersonIdOrderBySeqAscIdAsc(into.getSheetId(), into.getId());
        long first = own.isEmpty() ? 1 : own.get(0).getSeq() - theirs.size();
        for (int i = 0; i < theirs.size(); i++) {
            theirs.get(i).moveTo(into.getSheetId(), into.getId(), first + i);
        }
        saveAllAndFlush(theirs);
    }
}
